import{_ as e,o as i,c as a,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Using Rook in Production on National Research Platform - Dmitry Mishin, UCSD SDSC","description":"","frontmatter":{"title":"Using Rook in Production on National Research Platform - Dmitry Mishin, UCSD SDSC","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Rook","Ceph","Kubernetes","Distributed Storage","Cloud Computing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Using_Rook_in_Production_on_National_Research_Platform_-_Dmitry_Mishin_UCSD_SDSC.md","filePath":"posts/2025/Using_Rook_in_Production_on_National_Research_Platform_-_Dmitry_Mishin_UCSD_SDSC.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Using_Rook_in_Production_on_National_Research_Platform_-_Dmitry_Mishin_UCSD_SDSC.md"};function r(n,o,s,h,_,u){return i(),a("div",null,[...o[0]||(o[0]=[l('<p>在本次会议中，Dmitry Mishin（San Diego Supercomputer Center, UCSD）分享了National Research Platform（NRP）项目中使用Rook管理Ceph分布式存储的经验。以下是会议内容的总结：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><ul><li>主讲人：Dmitry Mishin</li><li>主题：NRP项目中使用Rook管理Ceph分布式存储的经验分享</li><li>背景：NRP是一个由70多个教育机构组成的科研计算平台，提供免费的计算资源和网络实验环境。</li></ul><h3 id="nrp项目简介" tabindex="-1">NRP项目简介 <a class="header-anchor" href="#nrp项目简介" aria-label="Permalink to &quot;NRP项目简介&quot;">​</a></h3><ul><li>NRP最初用于测量高校间科学网络链路性能，后发展为基于Kubernetes的大规模集群。</li><li>资源规模：1500+ GPUs，30000 CPU核心，177TB RAM，存储集群总容量13PB（800+ OSDs）。</li><li>网络架构：全美节点通过Science DMZ互联，支持跨地域存储访问。</li></ul><h3 id="ceph与rook的集成模式" tabindex="-1">Ceph与Rook的集成模式 <a class="header-anchor" href="#ceph与rook的集成模式" aria-label="Permalink to &quot;Ceph与Rook的集成模式&quot;">​</a></h3><ul><li>NRP中Ceph主要通过Rook管理，讨论了四种集成方式： <ol><li>Rook全托管模式：Rook自动部署Ceph（包括CSI Driver），简化管理。</li><li>Rook外部集群模式：手动部署Ceph，Rook仅管理Kubernetes端接入。</li><li>手动安装CSI Driver：直接对接已有Ceph集群，NRP未使用此模式。</li><li>Host Path直连模式：节点直接挂载CephFS/RBD，适用于Slurm/Lustre环境。</li></ol></li></ul><h3 id="nrp中的ceph存储池现状" tabindex="-1">NRP中的Ceph存储池现状 <a class="header-anchor" href="#nrp中的ceph存储池现状" aria-label="Permalink to &quot;NRP中的Ceph存储池现状&quot;">​</a></h3><ul><li>多集群部署：8个Ceph集群，部分区域/本地专用。</li><li>数据规模：12000+ Persistent Volumes (PVs)，800+ OSDs。</li></ul><h3 id="rook的优势与挑战" tabindex="-1">Rook的优势与挑战 <a class="header-anchor" href="#rook的优势与挑战" aria-label="Permalink to &quot;Rook的优势与挑战&quot;">​</a></h3><p><strong>优势</strong>：</p><ul><li>快速部署：自动配置Ceph和CSI Driver，适合中小规模集群。</li><li>Kubernetes原生管理：通过Pod/Logs监控组件，无需SSH。</li><li>资源调度：Kubernetes自动分配MDS/OSD等资源。</li></ul><p><strong>挑战</strong>（多集群大规模场景）：</p><ul><li>集群管理耦合：单个集群故障可能阻塞其他集群的操作（如升级）。</li><li>NVMe限制：单NVMe盘用于BlueStore/RocksDB，故障需整节点替换。</li><li>性能与扩展性问题：过去Rook Operator因并发读取ConfigMap导致API过载（已修复），配置变更耗时。</li></ul><h3 id="结论与建议" tabindex="-1">结论与建议 <a class="header-anchor" href="#结论与建议" aria-label="Permalink to &quot;结论与建议&quot;">​</a></h3><ul><li>推荐场景：中小规模Kubernetes集群（如云环境快速部署）。</li><li>注意事项： <ul><li>多大型集群需预先评估管理耦合风险。</li><li>优先使用Host Network（避免Overlay性能损耗）。</li></ul></li></ul><h3 id="q-a环节" tabindex="-1">Q&amp;A环节 <a class="header-anchor" href="#q-a环节" aria-label="Permalink to &quot;Q&amp;A环节&quot;">​</a></h3><ul><li>讨论聚焦于多集群运维经验和NVMe优化方案。</li></ul><p>Dmitry Mishin在会议中分享了NRP项目使用Rook管理Ceph的经验，并讨论了Rook在多集群大规模场景下的优势与挑战。这对希望了解Rook在实际生产环境中应用情况的技术人员具有重要的参考价值。</p>',19)])])}const d=e(t,[["render",r]]);export{c as __pageData,d as default};
